arguments:
{"script":"read chars words lines < <(find test_directory -type f -name '*.txt' -exec cat {} + | wc -c -w -l)
folders=$(find test_directory -type d | wc -l)
echo $((chars+words+lines+folders))
"}

{"script":"chars=$(find test_directory -type f -name '*.txt' -exec cat {} + 2>/dev/null | wc -c)
words=$(find test_directory -type f -name '*.txt' -exec cat {} + 2>/dev/null | wc -w)
lines=$(find test_directory -type f -name '*.txt' -exec cat {} + 2>/dev/null | wc -l)
folders=$(find test_directory -type d 2>/dev/null | wc -l)
echo $((chars+words+lines+folders))
"}
